head.script:
scwin.onpageload = function () {

};

scwin.btn_read_onclick = function (e) {
    var data = [];
    data[3000000 - 1] = "lastRow";
    dataList1.setData(data);
};

	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('gridView1_cell_21_0').innerText == 'lastRow';
	}	
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "1000");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_read').click()");
		WebSquare.wUnit.addCommand("pause", "700");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_scrollY_div').scrollTop = 100000000");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_scrollY_div').scrollTop = 10000000");
		WebSquare.wUnit.addCommand("pause", "500");				
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_scrollY_div').scrollTop = 100000000");
		WebSquare.wUnit.addCommand("pause", "500");				

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");		
		WebSquare.wUnit.addCommand("pause", "500");	
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest()
